-- 1. Widen CrmCourseRequirement text-bearing VARCHAR(191) columns so official
--    multi-clause university admission requirements (e.g. ECTS subject breakdowns)
--    publish cleanly on MySQL 8 without P2000 truncation.
ALTER TABLE `CrmCourseRequirement`
    MODIFY COLUMN `academicReq` VARCHAR(2048) NOT NULL DEFAULT '',
    MODIFY COLUMN `englishTest` VARCHAR(512) NOT NULL DEFAULT '',
    MODIFY COLUMN `componentScores` VARCHAR(512) NOT NULL DEFAULT '{}',
    MODIFY COLUMN `workExperience` VARCHAR(512) NOT NULL DEFAULT '',
    MODIFY COLUMN `countrySpecificRequirement` VARCHAR(512) NOT NULL DEFAULT '',
    MODIFY COLUMN `officialRequirementUrl` VARCHAR(512) NOT NULL DEFAULT '';

-- 2. Add the Password English Language Test family to english_tests when absent
--    so additive migrations match REQUIRED_TEST_SLUGS in src/lib/language-prep/editorial.ts.
INSERT INTO `english_tests` (`id`, `slug`, `name`, `shortName`, `shortDescription`, `longDescription`, `testType`, `provider`, `officialUrl`, `format`, `durationMinutes`, `durationDisplay`, `scoringSystem`, `resultTimeline`, `sourceUrl`, `costSummary`, `validitySummary`, `bestFor`, `acceptanceSummary`, `difficultyLevel`, `status`, `isPopular`, `isFeatured`, `sortOrder`, `sourceName`, `verifiedBy`, `verificationStatus`, `seoTitle`, `seoDescription`, `lastVerifiedAt`, `createdAt`, `updatedAt`)
SELECT 'test-password', 'password', 'Password English Language Test', 'Password', 'An online, CEFR-aligned English test used by universities for admission. It is not a UKVI-approved SELT.', 'The Password English Language Test is an online, CEFR-aligned English proficiency assessment produced by Password English Language Testing Ltd and academically validated by CRELLA (Centre for Research in English Language Learning and Assessment) at the University of Bedfordshire. Password Skills Plus covers reading, writing, listening and speaking, is taken online under live proctoring by Meazure Learning, and result certificates are normally emailed within five working days. It is used by universities and pathway providers for admission and pre-sessional placement. It is not on the UK Home Office list of approved Secure English Language Tests, so it cannot be used where a visa route requires a SELT.', 'english_proficiency', 'Password English Language Testing Ltd', 'https://passwordplus.englishlanguagetesting.co.uk/', 'Online, live-proctored, taken at home or at an approved location', 185, 'About 3h 05m online, live-proctored', 'CEFR-aligned Password score across reading, writing, listening and speaking', 'Result certificates emailed within five working days.', 'https://passwordplus.englishlanguagetesting.co.uk/', 'Fees depend on location, delivery mode and booking date. View the provider booking price before payment.', 'Recency rules are set by the receiving institution.', 'Applicants to universities and pathway providers that name the Password test.', 'Confirm the exact exam, delivery mode and minimum score with your university. Visa evidence rules are separate; a university offer does not confirm visa eligibility.', 'Academic English across four skills', 'active', 0, 0, 16, 'Password English Language Testing Ltd (official)', 'Official-source editorial review', 'verified', 'Password English Language Test | Preparation & Acceptance | ALO Education', 'Password English Language Test guidance — online format, modules, CEFR-aligned results, university acceptance and the UKVI SELT position.', '2026-10-29 00:00:00.000', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `english_tests` WHERE `slug` = 'password' OR `id` = 'test-password');
